"""gen_demo_seeds - writes demo/master_seed.sql and demo/license_project_seed.sql from constants.json and themes/*.json. Placeholders only; no secrets.
Run: python3 -I gen_demo_seeds.py"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lbmodel import SHARED, load_constants  # noqa: E402

C = load_constants()
D = C['demo']
plans = C['limits']['plans']
flags = C['flags']['plan_defaults']
j = lambda o: json.dumps(o, separators=(',', ':'))
q = lambda s: s.replace("'", "''")

m = ['-- demo/master_seed.sql - GENERATED by fixtures/tools/gen_demo_seeds.py from constants.json and themes/*.json. Do not edit by hand.',
     '-- Run in the MASTER Supabase project AFTER sql/01_master_schema.sql. Idempotent. Contains placeholders only: replace the project URL and anon key',
     '-- after creating your license project (see demo/STANDALONE_RUN.md). No secret of any kind belongs in this file.', '',
     '-- 1. plans: full flag sets from constants.json flags.plan_defaults (the schema file seeds only a subset; this makes them complete)']
for pid, name in (('basic', 'Basic'), ('pro', 'Pro')):
    m.append("insert into public.plans(id,name,features,limits) values ('%s','%s','%s'::jsonb,'%s'::jsonb)\n  on conflict (id) do update set features = excluded.features, limits = excluded.limits;" % (pid, name, j(flags[pid]), j(plans[pid])))
m += ['', '-- 2. demo customer, license project (placeholders) and the demo license', "insert into public.customers(id,name,email,city,notes) values ('00000000-0000-4000-8000-0000000000c1','%s','%s','Pune','Demo data. Fictional.')\n  on conflict (id) do nothing;" % (q(D['company_name']), D['owner_email']),
      "insert into public.supabase_projects(id,name,url,anon_key,status,capacity,schema_version) values ('00000000-0000-4000-8000-0000000000a1','demo-license-project','https://YOUR-LICENSE-PROJECT-REF.supabase.co','YOUR-LICENSE-PROJECT-ANON-KEY','active',1,1)\n  on conflict (id) do nothing;",
      "insert into public.licenses(license_key,customer_id,company_name,plan_id,is_active,expires_at,max_devices,max_companies,project_id,theme_policy,notes) values ('%s','00000000-0000-4000-8000-0000000000c1','%s','pro',true,now() + interval '5 years',%d,%d,'00000000-0000-4000-8000-0000000000a1','%s'::jsonb,'Reserved demo license. Fictional.')\n  on conflict (license_key) do nothing;" % (D['license_key'], q(D['company_name']), plans['pro']['max_devices'], plans['pro']['max_companies'], j(C['themes']['default_policy'])),
      '', '-- 3. built-in themes (validated against THEME_SCHEMA.md)']
for slug in C['themes']['builtin_slugs']:
    t = json.load(open(os.path.join(SHARED, 'themes', slug + '.json')))
    m.append("insert into public.themes(slug,name,version,schema_version,json,is_default,is_active) values ('%s','%s',%d,%d,$lbjson$%s$lbjson$::jsonb,%s,true)\n  on conflict (slug) do update set json = excluded.json, version = excluded.version, name = excluded.name;" % (slug, q(t['name']), t['version'], t['schema_version'], j(t), 'true' if slug == C['themes']['default_slug'] else 'false'))
m += ['', '-- 4. global branding set (no assets yet; the app falls back to built-in branding)',
      "insert into public.branding_sets(scope,version,assets,app_name,is_active)\n  select 'global',1,'{}'::jsonb,'%s',true where not exists (select 1 from public.branding_sets where scope = 'global');" % C['branding']['app_name_default'],
      '', '-- 5. first admin: create the user in Supabase Auth (dashboard, email + password) with this email, then this row links it. Safe to re-run.',
      "insert into public.admins(user_id,email,role)\n  select id, email, 'owner' from auth.users where lower(email) = lower('%s')\n  on conflict (user_id) do nothing;" % D['admin_email'], '']
open(os.path.join(SHARED, 'demo', 'master_seed.sql'), 'w').write('\n'.join(m))

l = ['-- demo/license_project_seed.sql - GENERATED by fixtures/tools/gen_demo_seeds.py. Run in the LICENSE Supabase project AFTER sql/02_license_project_schema.sql. Idempotent.', '',
     "insert into public.license_meta(license_key,schema_version) values ('%s',1) on conflict (license_key) do nothing;" % D['license_key'],
     "insert into public.app_settings(license_key,key,value) values\n  ('%s','company_guid','\"%s\"'::jsonb),\n  ('%s','quotation_voucher_type_guid','\"%s\"'::jsonb)\n  on conflict (license_key,key) do update set value = excluded.value;" % ('%s', '%s', '%s', '%s'), '']
comp = json.load(open(os.path.join(SHARED, 'fixtures', 'tables', 'tm_company.json')))[0]['guid']
vts = json.load(open(os.path.join(SHARED, 'fixtures', 'tables', 'tm_voucher_type.json')))
qg = next(v['guid'] for v in vts if v['name'] == 'Sales Quotation')
l[3] = "insert into public.app_settings(license_key,key,value) values\n  ('%s','company_guid','\"%s\"'::jsonb),\n  ('%s','quotation_voucher_type_guid','\"%s\"'::jsonb)\n  on conflict (license_key,key) do update set value = excluded.value;" % (D['license_key'], comp, D['license_key'], qg)
vec = json.load(open(os.path.join(SHARED, 'crypto_vectors.json')))
l.append("insert into public.app_settings(license_key,key,value) values\n  ('%s','crypto_salt_b64','\"%s\"'::jsonb),\n  ('%s','crypto_kcv','\"%s\"'::jsonb)\n  on conflict (license_key,key) do update set value = excluded.value;" % (D['license_key'], vec['kdf']['salt_b64'], D['license_key'], vec['kcv']['value']))
l.append('-- Demo passphrase (constants.json demo.passphrase) with this salt gives the key of crypto_vectors.json; the demo sync_examples use the test license key instead.')
l += ['-- Logins (owner and connector) are created in Supabase Auth with app_metadata {"license_key": "%s", "role": "owner" | "connector"}.' % D['license_key'],
      '-- Emails and passwords are never stored in files: %s and %s are placeholders; set real ones in the dashboard.' % (D['owner_email'], D['connector_email']), '']
open(os.path.join(SHARED, 'demo', 'license_project_seed.sql'), 'w').write('\n'.join(l))
print('ok')
